package identity

import (
	"encoding/base64"
	"golang.org/x/crypto/bcrypt"
)

// PasswordInstalled distinguishes an actual bcrypt credential from an absent
// or malformed value. A NULL password never supplies password confirmation.
func PasswordInstalled(hash []byte) bool {
	// Accept the exact format/cost generated by the current password writer.
	// Cost alone does not validate the salt/hash encoding in x/crypto/bcrypt.
	if len(hash) != 60 || string(hash[:4]) != "$2a$" || hash[6] != '$' {
		return false
	}
	cost, err := bcrypt.Cost(hash)
	if err != nil || cost != PasswordCost {
		return false
	}
	encoding := base64.NewEncoding("./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789").WithPadding(base64.NoPadding).Strict()
	salt, err := encoding.DecodeString(string(hash[7:29]))
	if err != nil || len(salt) != 16 {
		return false
	}
	checksum, err := encoding.DecodeString(string(hash[29:]))
	return err == nil && len(checksum) == 23
}

// passwordMatches keeps absent credentials on the same bounded bcrypt work
// path as an incorrect password. Callers acquire the existing password slot.
func (s *Service) passwordMatches(hash []byte, password string) bool {
	installed := PasswordInstalled(hash)
	candidate := hash
	if !installed {
		candidate = s.dummy
	}
	valid := bcrypt.CompareHashAndPassword(candidate, []byte(password)) == nil
	return installed && valid
}
